WITH lines AS (SELECT id, currency, EXPLODE(tier_prices) AS element FROM price_tiers), scored AS (SELECT id, currency, element, PERCENT_RANK() OVER (PARTITION BY currency ORDER BY element DESC) AS element_percent_rank, COUNT(element) OVER (PARTITION BY currency) AS currency_count_element, STDDEV_SAMP(element) OVER (PARTITION BY currency) AS currency_stddev_samp_element, SUM(element) OVER (PARTITION BY currency) AS currency_sum_element, MAX(element) OVER (PARTITION BY currency) AS currency_max_element FROM lines), valid AS (SELECT *, currency_max_element + element_percent_rank AS currency_max_element_plus_element_percent_rank, CASE WHEN currency_max_element >= 76 THEN 'High' WHEN currency_max_element >= 30 THEN 'Medium' ELSE 'Low' END AS currency_max_element_band FROM scored WHERE currency_sum_element <= 250), metrics AS (SELECT id, currency, element, element_percent_rank, currency_count_element, currency_stddev_samp_element, currency_sum_element, currency_max_element, currency_max_element_plus_element_percent_rank, currency_max_element_band, ROUND(currency_count_element / SUM(currency_count_element) OVER (PARTITION BY currency), 4) AS currency_count_element_share, STDDEV_SAMP(currency_sum_element) OVER (PARTITION BY currency) AS currency_stddev_samp_currency_sum_element FROM valid), totals AS (SELECT CASE WHEN element >= 76 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, CASE WHEN currency_count_element_share >= 0.71 THEN 'PREMIUM' ELSE 'STANDARD' END AS currency_count_element_share_tier, COUNT_IF(currency = 'THB') AS thb_events, ROUND(AVG(currency_count_element_share), 2) AS avg_currency_count_element_share, ROUND(AVG(currency_count_element_share), 2) AS avg_currency_count_element_share_2, GROUPING(CASE WHEN element >= 76 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_id FROM metrics GROUP BY GROUPING SETS ((CASE WHEN element >= 76 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN currency_count_element_share >= 0.71 THEN 'PREMIUM' ELSE 'STANDARD' END), (CASE WHEN element >= 76 THEN 'PREMIUM' ELSE 'STANDARD' END))) SELECT element_tier, avg_currency_count_element_share_2, grouping_id FROM totals
